import{_ as c,C as h,o as a,c as l,a3 as o,b as n,w as t,a as i,E as r,a4 as d}from"./chunks/framework.XGrxkBzI.js";const f=JSON.parse(`{"title":"The server's database","description":"","frontmatter":{},"headers":[],"relativePath":"docs/database.md","filePath":"docs/database.md"}`),u={name:"docs/database.md"};function A(g,e,m,p,_,b){const s=h("Mermaid");return a(),l("div",null,[e[3]||(e[3]=o('<h1 id="the-server-s-database" tabindex="-1">The server&#39;s database <a class="header-anchor" href="#the-server-s-database" aria-label="Permalink to &quot;The server&#39;s database&quot;">​</a></h1><p>The tables of the server&#39;s Postgres database, how they relate, and why they are shaped this way. Read it before changing the schema or writing a query. The phone keeps its own, different database (<a href="#the-phones-database">the phone&#39;s database</a>).</p><p>The schema is the numbered migrations in <code>server/src/main/sqldelight/migrations</code>, applied on start (<a href="./adr/0022-the-servers-schema-is-sqldelight-migrations-on-postgres">ADR 0022</a>); the typed queries sit beside them in <code>.sq</code> files. When this page and a migration disagree, the migration is right.</p><h2 id="how-it-is-shaped" tabindex="-1">How it is shaped <a class="header-anchor" href="#how-it-is-shaped" aria-label="Permalink to &quot;How it is shaped&quot;">​</a></h2><ul><li><strong>Columns for structure, JSONB for content</strong> (<a href="./adr/0007-postgres-columns-for-structure-jsonb-for-content">ADR 0007</a>). What the server filters, sorts or joins on is a column. A workout, a session&#39;s events and an exercise are JSONB read with the shared Kotlin types.</li><li><strong>Everything of a person hangs off <code>account</code>.</strong> Deleting an account deletes its rows, except its audit trail.</li><li><strong>Tokens are stored as SHA-256 hashes</strong>, never as the token, so a leaked table opens nothing.</li><li><strong>Synced rows carry a <code>change_number</code></strong>, the account&#39;s next change count, so a pull after a number never misses a row (<a href="./sync#pull">Sync</a>, <a href="./adr/0025-the-phone-forks-a-conflicting-workout-and-the-server-counts-changes">ADR 0025</a>).</li><li><strong>Nothing is deleted from the sync tables without a trace.</strong> A deletion is a row that says so, so it reaches every phone.</li></ul><h2 id="accounts-and-sign-in" tabindex="-1">Accounts and sign-in <a class="header-anchor" href="#accounts-and-sign-in" aria-label="Permalink to &quot;Accounts and sign-in&quot;">​</a></h2><p>An account, its sign-ins (one per phone or browser) and the short-lived secrets that belong to them. The rules a person sees are in <a href="./accounts">Accounts</a>.</p>',7)),(a(),n(d,null,{default:t(()=>[r(s,{id:"mermaid-45",class:"mermaid",graph:"erDiagram%0A%20%20%20%20account%20%7C%7C--o%7B%20sign_in%20%3A%20%22has%22%0A%20%20%20%20account%20%7C%7C--o%7B%20confirmation_token%20%3A%20%22confirms%20with%22%0A%20%20%20%20account%20%7C%7C--o%7B%20confirmation_watch%20%3A%20%22watched%20by%22%0A%20%20%20%20account%20%7C%7C--o%7B%20password_reset_token%20%3A%20%22resets%20with%22%0A%20%20%20%20sign_in%20%7C%7C--o%7B%20access_token%20%3A%20%22holds%22%0A%20%20%20%20sign_in%20%7C%7C--o%7B%20refresh_token%20%3A%20%22holds%22%0A%20%20%20%20account%20%7B%0A%20%20%20%20%20%20%20%20uuid%20id%20PK%0A%20%20%20%20%20%20%20%20text%20email%20%22unique%2C%20any%20case%22%0A%20%20%20%20%20%20%20%20text%20password_hash%20%22Argon2id%22%0A%20%20%20%20%20%20%20%20text%20role%20%22member%20or%20admin%22%0A%20%20%20%20%20%20%20%20timestamptz%20confirmed_at%20%22null%20until%20confirmed%22%0A%20%20%20%20%20%20%20%20timestamptz%20disabled_at%20%22null%20while%20in%20use%22%0A%20%20%20%20%20%20%20%20bigint%20change_count%20%22last%20change%20number%22%0A%20%20%20%20%7D%0A%20%20%20%20sign_in%20%7B%0A%20%20%20%20%20%20%20%20uuid%20id%20PK%0A%20%20%20%20%20%20%20%20uuid%20account_id%20FK%0A%20%20%20%20%20%20%20%20text%20device_name%0A%20%20%20%20%20%20%20%20timestamptz%20revoked_at%0A%20%20%20%20%7D%0A%20%20%20%20sign_in_failure%20%7B%0A%20%20%20%20%20%20%20%20text%20email%0A%20%20%20%20%20%20%20%20timestamptz%20failed_at%0A%20%20%20%20%7D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[i(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=o('<ul><li><code>access_token</code> and <code>refresh_token</code> belong to a sign-in, so they live and die together. A refresh token works once and is kept after use, so a second use revokes the whole sign-in (<a href="./adr/0020-every-credential-resolves-to-one-caller">ADR 0020</a>).</li><li><code>confirmation_watch</code> lets a phone waiting on &quot;Check your email&quot; ask whether the link was opened, with a key whose hash is stored.</li><li><code>sign_in_failure</code> has no account column: it counts failed attempts per address, to slow down password guessing.</li></ul><h2 id="synced-data" tabindex="-1">Synced data <a class="header-anchor" href="#synced-data" aria-label="Permalink to &quot;Synced data&quot;">​</a></h2><p>What a phone pushes and pulls, all owned by an account. Each table keeps the account first in its key, so a person&#39;s rows sit together.</p>',3)),(a(),n(d,null,{default:t(()=>[r(s,{id:"mermaid-69",class:"mermaid",graph:"erDiagram%0A%20%20%20%20account%20%7C%7C--o%7B%20session%20%3A%20%22owns%22%0A%20%20%20%20session%20%7C%7C--o%7B%20session_event%20%3A%20%22records%22%0A%20%20%20%20account%20%7C%7C--o%7B%20workout_version%20%3A%20%22owns%22%0A%20%20%20%20account%20%7C%7C--o%7B%20workout_deletion%20%3A%20%22owns%22%0A%20%20%20%20account%20%7C%7C--o%7B%20planned_workout%20%3A%20%22owns%22%0A%20%20%20%20account%20%7C%7C--o%7B%20body_measurement%20%3A%20%22owns%22%0A%20%20%20%20account%20%7C%7C--o%7B%20setting%20%3A%20%22owns%22%0A%20%20%20%20session%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20uuid%20id%20PK%0A%20%20%20%20%20%20%20%20uuid%20workout_id%20%22no%20foreign%20key%22%0A%20%20%20%20%20%20%20%20timestamptz%20deleted_at%0A%20%20%20%20%20%20%20%20jsonb%20totals%0A%20%20%20%20%20%20%20%20bigint%20change_number%0A%20%20%20%20%7D%0A%20%20%20%20session_event%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20uuid%20session_id%20PK%0A%20%20%20%20%20%20%20%20bigint%20seq%20PK%0A%20%20%20%20%20%20%20%20jsonb%20payload%0A%20%20%20%20%20%20%20%20bigint%20change_number%0A%20%20%20%20%7D%0A%20%20%20%20workout_version%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20uuid%20workout_id%20PK%0A%20%20%20%20%20%20%20%20int%20version%20PK%0A%20%20%20%20%20%20%20%20jsonb%20content%0A%20%20%20%20%20%20%20%20bigint%20change_number%0A%20%20%20%20%7D%0A%20%20%20%20workout_deletion%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20uuid%20workout_id%20PK%0A%20%20%20%20%20%20%20%20int%20version%0A%20%20%20%20%7D%0A%20%20%20%20planned_workout%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20uuid%20id%20PK%0A%20%20%20%20%20%20%20%20uuid%20workout_id%0A%20%20%20%20%20%20%20%20date%20day%0A%20%20%20%20%20%20%20%20boolean%20deleted%0A%20%20%20%20%7D%0A%20%20%20%20body_measurement%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20text%20metric%20PK%0A%20%20%20%20%20%20%20%20date%20day%20PK%0A%20%20%20%20%20%20%20%20double%20value%20%22null%20once%20deleted%22%0A%20%20%20%20%7D%0A%20%20%20%20setting%20%7B%0A%20%20%20%20%20%20%20%20uuid%20account_id%20PK%0A%20%20%20%20%20%20%20%20text%20key%20PK%0A%20%20%20%20%20%20%20%20text%20value%20%22null%20once%20cleared%22%0A%20%20%20%20%7D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[i(" Loading... ",-1)])]),_:1})),e[5]||(e[5]=o('<p>Two kinds of table, by how conflicts are settled (<a href="./adr/0006-sync-keeps-both-edits">ADR 0006</a>):</p><ul><li><strong>Never changed once stored.</strong> <code>session_event</code> (<a href="./adr/0003-sessions-are-append-only-event-logs">ADR 0003</a>) and <code>workout_version</code>. A push may only add the version that follows the latest; a phone that edited an older one forks a new workout.</li><li><strong>Latest write wins.</strong> <code>planned_workout</code>, <code>body_measurement</code> and <code>setting</code> keep the write with the latest <code>changed_at</code> the phone sent. A deletion is a write: <code>deleted</code>, or a null value.</li></ul><p><code>workout_id</code> is not a foreign key: a workout is its versions, not a row. <code>session</code> and <code>workout_deletion</code> also keep a deletion as a row (<code>deleted_at</code>, or the deleted version). A newer version pushed after a deletion removes the <code>workout_deletion</code> row, so the edit wins.</p><h2 id="the-catalog" tabindex="-1">The catalog <a class="header-anchor" href="#the-catalog" aria-label="Permalink to &quot;The catalog&quot;">​</a></h2><p>The exercises phones download, edited and published in the admin (<a href="./the-catalog">The catalog&#39;s shape</a>, <a href="./adr/0026-the-server-holds-the-catalog-as-a-draft-and-published-versions">ADR 0026</a>, <a href="./adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>). It belongs to no account.</p>',5)),(a(),n(d,null,{default:t(()=>[r(s,{id:"mermaid-94",class:"mermaid",graph:"erDiagram%0A%20%20%20%20catalog_exercise_revision%20%7B%0A%20%20%20%20%20%20%20%20text%20slug%20PK%0A%20%20%20%20%20%20%20%20int%20revision%20PK%0A%20%20%20%20%20%20%20%20int%20position%20%22catalog%20order%22%0A%20%20%20%20%20%20%20%20jsonb%20content%20%22the%20shared%20Exercise%22%0A%20%20%20%20%20%20%20%20int%20variation_group%0A%20%20%20%20%20%20%20%20int%20variation_rank%20%22easiest%20first%22%0A%20%20%20%20%20%20%20%20bigint%20seq%20%22null%20for%20the%20draft%22%0A%20%20%20%20%20%20%20%20timestamptz%20created_at%0A%20%20%20%20%7D%0A%20%20%20%20catalog_publication%20%7B%0A%20%20%20%20%20%20%20%20int%20id%20PK%20%22always%201%22%0A%20%20%20%20%20%20%20%20bigint%20last_seq%0A%20%20%20%20%7D%0A"})]),fallback:t(()=>[...e[2]||(e[2]=[i(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=o('<ul><li><strong>One row per revision of one exercise.</strong> A slug has at most one draft revision (no <code>seq</code>) and any number of published ones. Published revisions are never changed.</li><li><strong><code>seq</code> is the publication cursor.</strong> A publish takes the next numbers from <code>catalog_publication</code>, under that row&#39;s lock, so <code>seq</code> follows commit order and a phone asks for what is after the last <code>seq</code> it has.</li><li><strong>The current catalog</strong> is, for each slug, its revision with the highest <code>seq</code>.</li></ul><details><summary>Tables kept until a cleanup migration</summary><p><code>catalog_version</code> and <code>catalog_exercise_revision.published_in</code> are still in the schema but nothing reads them, now that publications are numbered by <code>seq</code>. A later migration drops them (<a href="./adr/0030-the-catalog-changes-by-exercise-revision-not-by-catalog-version">ADR 0030</a>, #440).</p></details><h2 id="admin-and-housekeeping" tabindex="-1">Admin and housekeeping <a class="header-anchor" href="#admin-and-housekeeping" aria-label="Permalink to &quot;Admin and housekeeping&quot;">​</a></h2><p>Three tables with no part in the diagrams above.</p><table tabindex="0"><thead><tr><th>Table</th><th>What it holds</th></tr></thead><tbody><tr><td><code>admin_audit</code></td><td>One row per admin write: who (<code>actor_id</code>, null once that admin&#39;s account is deleted), what (<code>action</code>), on what (<code>target</code>, such as an account id or an exercise slug), and when. See <a href="./admin-internals#audit-log">Admin internals</a>.</td></tr><tr><td><code>settings</code></td><td>Server settings an admin changes without a deploy, one row per name. A setting with no row keeps its default from the environment, and secrets never live here (<a href="./admin-internals#settings-and-mail">Admin internals</a>). Not to be confused with <code>setting</code>, the person&#39;s synced preferences.</td></tr><tr><td><code>schema_version</code></td><td>One row: the number of the next migration to apply. Kept by <code>Database.migrate</code>.</td></tr></tbody></table><h2 id="the-phone-s-database" tabindex="-1">The phone&#39;s database <a class="header-anchor" href="#the-phone-s-database" aria-label="Permalink to &quot;The phone&#39;s database&quot;">​</a></h2><p>The phone has its own SQLite database in <code>data/local</code>, with its own numbered migrations. It is the source of truth (<a href="./adr/0001-local-first-phone-is-the-source-of-truth">ADR 0001</a>) and has no owner column. It holds the same synced kinds (sessions and their events, workout versions, planned workouts, body measurements), the catalog it downloaded, and the sync state: an outbox of changes to push and the cursors of the last pull. Sync moves documents between the two, not tables, so the schemas are free to differ.</p>',7))])}const k=c(u,[["render",A]]);export{f as __pageData,k as default};
